add_action( 'woocommerce_process_shop_order_meta', 'perfectpixel_auto_send_payment_request', 70 );

// Runs after WooCommerce saved the order from the edit screen.
function perfectpixel_auto_send_payment_request( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( ! $order || ! $order->has_status( 'pending' ) || $order->get_meta( '_perfectpixel_invoice_sent' ) ) {
		return;
	}
	if ( ! $order->get_billing_email() || ! $order->get_item_count() || (float) $order->get_total() <= 0 ) {
		return;
	}
	$emails = WC()->mailer()->get_emails();
	if ( isset( $emails['WC_Email_Customer_Invoice'] ) ) {
		$emails['WC_Email_Customer_Invoice']->trigger( $order->get_id(), $order );
		$order->update_meta_data( '_perfectpixel_invoice_sent', current_time( 'mysql' ) );
		$order->add_order_note( 'Τα στοιχεία παραγγελίας με σύνδεσμο πληρωμής στάλθηκαν αυτόματα στον πελάτη.', false, true );
		$order->save();
	}
}
